import re
names = ["Chapter 10", "Chapter 2", "Appendix A", "Chapter 1", "Chapter 10a", "Appendix B", "Chapter 21"]
def chapter_key(name):
    m = re.fullmatch(r"Chapter (\d+)([a-z]?)", name)
    if m:
        return (0, int(m.group(1)), m.group(2))
    return (1, 0, name)
for n in sorted(names, key=chapter_key):
    print(n)

import re
labels = ["10", "A2", "1", "B", "A10", "2", "A", "A1"]
def section_key(s):
    if s.isdigit():
        return (0, int(s), "", 0)
    m = re.fullmatch(r"([A-Z]+)(\d*)", s)
    letters, digits = m.group(1), m.group(2)
    return (1, 0, letters, int(digits) if digits else 0)
for s in labels:
    print(s, "->", section_key(s))
print("sorted:", sorted(labels, key=section_key))

import bisect, random
rng = random.Random(7)
data = sorted(rng.randrange(0, 500) for _ in range(2000))
def count_in_range(lo, hi):
    return bisect.bisect_left(data, hi) - bisect.bisect_left(data, lo)
for lo, hi in ((100, 200), (0, 500), (250, 251), (480, 999)):
    fast = count_in_range(lo, hi)
    slow = sum(1 for x in data if lo <= x < hi)
    print(f"[{lo}, {hi}): bisect={fast} brute={slow} match={fast == slow}")

def any_shared_slow(a, b):
    comparisons = 0
    for x in a:
        for y in b:
            comparisons += 1
            if x == y:
                return True, comparisons
    return False, comparisons
def any_shared_fast(a, b):
    bset = set(b)
    return any(x in bset for x in a)
A = list(range(0, 400, 2))
B = list(range(1, 600, 2))
print("slow (no shared element):", any_shared_slow(A, B))
print("fast result:", any_shared_fast(A, B))
A2 = list(range(200))
B2 = list(range(150, 400))
print("slow (shared exists):", any_shared_slow(A2, B2))
print("fast result:", any_shared_fast(A2, B2))

