import random
from functools import cmp_to_key
def make_cmp(seed):
    rng = random.Random(seed)
    def cmp(a, b):
        if a[1] != b[1]:
            return (a[1] > b[1]) - (a[1] < b[1])
        return rng.choice([-1, 1])
    return cmp
data = [("ana", 90), ("bo", 90), ("cy", 90), ("di", 80)]
run1 = sorted(data, key=cmp_to_key(make_cmp(1)))
run2 = sorted(data, key=cmp_to_key(make_cmp(4)))
print("run 1:", [n for n, s in run1])
print("run 2:", [n for n, s in run2])
print("same input, different order:", run1 != run2)

from functools import cmp_to_key
beats = {("rock", "scissors"), ("scissors", "paper"), ("paper", "rock")}
def cmp(a, b):
    if a == b:
        return 0
    return -1 if (a, b) in beats else 1
for perm in (["rock", "paper", "scissors"], ["paper", "scissors", "rock"], ["scissors", "rock", "paper"]):
    print(perm, "->", sorted(perm, key=cmp_to_key(cmp)))

from functools import cmp_to_key
import re
tags = ["build9", "build10", "build2", "build10a", "build1"]
def old_cmp(a, b):
    return (a > b) - (a < b)
old = sorted(tags, key=cmp_to_key(old_cmp))
print("old comparator (plain string order):", old)
def tag_key(t):
    m = re.fullmatch(r"build(\d+)([a-z]?)", t)
    return (int(m.group(1)), m.group(2))
new = sorted(tags, key=tag_key)
print("key version (numeric order):       ", new)
